create table users (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, name varchar(255) not null, email varchar(255) not null unique, password_hash varchar(255) not null, role varchar(30) not null, enabled boolean not null);
create table categories (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, name varchar(255) not null unique, slug varchar(255) unique, description varchar(255));
create table products (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, name varchar(255) not null, slug varchar(255) not null unique, description text, price numeric(12,2) not null, active boolean not null, category_id uuid not null references categories(id));
create index idx_product_slug on products(slug); create index idx_product_category on products(category_id);
create table inventory (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, product_id uuid not null unique references products(id), quantity integer not null, version bigint not null);
create table carts (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, user_id uuid not null unique references users(id));
create table cart_items (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, cart_id uuid not null references carts(id), product_id uuid not null references products(id), quantity integer not null, unique(cart_id,product_id));
create table addresses (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, user_id uuid not null references users(id), line1 varchar(255) not null, line2 varchar(255), city varchar(255) not null, state varchar(255) not null, postal_code varchar(255) not null, country varchar(255) not null);
create table orders (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, user_id uuid not null references users(id), status varchar(30) not null, subtotal numeric(12,2) not null, discount numeric(12,2) not null, total numeric(12,2) not null, shipping_address_snapshot text not null);
create index idx_order_user on orders(user_id);
create table order_items (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, order_id uuid not null references orders(id), product_id uuid not null references products(id), quantity integer not null, unit_price numeric(12,2) not null);
create table payments (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, order_id uuid not null unique references orders(id), reference varchar(255) not null unique, status varchar(30) not null, amount numeric(12,2) not null);
create table coupons (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, code varchar(255) not null unique, discount_percent numeric(5,2) not null, expires_at timestamp with time zone, active boolean not null);
create table reviews (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, user_id uuid not null references users(id), product_id uuid not null references products(id), rating integer not null, comment text, unique(user_id,product_id));
create table wishlist_items (id uuid primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, user_id uuid not null references users(id), product_id uuid not null references products(id), unique(user_id,product_id));
